INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Durante uma cirurgia laparoscópica abdominal, o anestesista nota queda súbita e acentuada do ETCO2 (gás carbônico expirado), hipotensão grave, taquicardia e um sopro em ''roda de moinho'' (mill-wheel murmur) à ausculta cardíaca. Qual a principal suspeita diagnóstica?", "options": {"a": "Choque Séptico imediato.", "b": "Embolia Gasosa (insuflação de CO2 intravascular).", "c": "Pneumotórax bilateral.", "d": "Reação anafilática ao bloqueador muscular.", "e": "Infarto agudo do miocárdio."}, "answer": "b", "rationale": "A embolia gasosa por CO2 é uma complicação rara mas grave da laparoscopia. O gás na câmara cardíaca direita impede o fluxo sanguíneo para os pulmões (gap de ar), causando o sopro característico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Reconhecimento de emergência técnica em laparoscopia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Anestesiologia", "Pós-operatório", "Laparoscopia", "Embolia Gasosa"]}', 251, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a manobra de posicionamento recomendada para um paciente com suspeita de embolia gasosa venosa transoperatória visando deslocar a bolha de ar do trato de saída do ventrículo direito?", "options": {"a": "Trendelenburg (cabeça para baixo) e decúbito lateral esquerdo (Manobra de Durant).", "b": "Posição de Fowler (sentado).", "c": "Trendelenburg e decúbito lateral direito.", "d": "Posição supina plana.", "e": "Posição de canivete."}, "answer": "a", "rationale": "O decúbito lateral esquerdo faz com que a bolha de ar suba para o ápice do ventrículo direito, longe da artéria pulmonar, prevenindo a obstrução mecânica definitiva.", "option_rationales": {"a": "Correta. Manobra clássica de salvação na embolia gasosa.", "b": "Incorreta. Favorece a saída da bolha para a circulação cerebral se houver shunt.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Embolia Gasosa", "Posicionamento"]}', 252, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia colorretal laparoscópica queixa-se no 1º DPO de dor intensa em ombro direito, sem sinais de trauma local ou alteração respiratória. O Raio-x de ombro é normal. Qual a causa provável?", "options": {"a": "Laringoespasmo residual.", "b": "Irritação do nervo frênico pelo CO2 residual no espaço subdiafragmático (dor referida).", "c": "Luxação de ombro durante o posicionamento.", "d": "Tendinite aguda por esforço.", "e": "Pneumonia de lobo superior."}, "answer": "b", "rationale": "A dor escapular é comum após laparoscopia por irritação diafragmática do pneumoperitônio. Costuma ceder em 24-48h.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fenômeno de dor referida típico da técnica laparoscópica.", "c": "Incorreta. O Raio-x seria alterado.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Laparoscopia", "Dor Referida"]}', 253, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal característica da ''Cefaleia Pós-Punção Dural'' (CPPD) que a diferencia de outras causas de cefaleia no pós-operatório é:", "options": {"a": "Piora ao deitar.", "b": "Unilateral e pulsátil.", "c": "Seu caráter nitidamente postural (piora ao sentar/levantar e melhora ao deitar).", "d": "Associada a picos hipertensivos.", "e": "Resistente a cafeína venosa."}, "answer": "c", "rationale": "A drenagem contínua de líquor pelo orifício da punção reduz a pressão liquórica; na posição vertical, o cérebro ''traciona'' as meninges por gravidade.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Critério diagnóstico postural clássico.", "d": "Incorreta.", "e": "Incorreta. A cafeína é um tratamento estabelecido."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "CPPD", "Neurologia"]}', 254, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 70 anos submetido a artroplastia total de quadril apresenta, no 2º DPO, taquipneia, confusão mental progressiva e petéquias em região axilar e conjuntiva palpebral. Qual a principal hipótese diagnóstica?", "options": {"a": "Choque Séptico por pneumonia.", "b": "Sindrome de Embolia Gordurosa (SEG).", "c": "Tromboembolismo Pulmonar maciço.", "d": "AVC isquêmico agudo.", "e": "Reação medicamentosa alérgica."}, "answer": "b", "rationale": "A SEG é clássica após fraturas e cirurgias de ossos longos/pelve. A tríade diagnóstica de Gurd envolve disfunção respiratória, disfunção neurológica e petéquias axilares.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tríade clínica clássica da embolia gordurosa.", "c": "Incorreta. TEP não costuma causar petéquias axilares.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Ortopedia", "Pós-operatório", "Embolia Gordurosa", "Sinais"]}', 255, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a conduta inicial recomendada para um paciente com diagnóstico de Síndrome de Embolia Gordurosa?", "options": {"a": "Anticoagulação plena imediata com Heparina.", "b": "Trombólise química.", "c": "Tratamento de suporte agressivo (oxigenação, manutenção da volemia e suporte ventilatório se necessário).", "d": "Administração de doses maciças de corticoides (controversa, não é primeira linha).", "e": "Amputação do membro."}, "answer": "c", "rationale": "Não existe tratamento específico para a embolia gordurosa para dissolver a gordura. O objetivo é manter o paciente vivo com suporte de órgãos até que a inflamação ceda.", "option_rationales": {"a": "Incorreta. A gordura não é um trombo de fibrina; a heparina não é o tratamento primário.", "b": "Incorreta.", "c": "Correta. Suporte de órgãos é o pilar fundamental.", "d": "Incorreta. Seu papel é muito debatido e não é a conduta inicial prioritária sobre o suporte respiratório.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Ortopedia", "Pós-operatório", "Embolia Gordurosa", "Manejo"]}', 256, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia urológica realizada em posição de litotomia exagerada por 6 horas, o paciente acorda com fraqueza para a dorsiflexão do pé direito (pé caído) e parestesia em face lateral da perna. Qual o nervo provavelmente lesionado por compressão no suporte de perna?", "options": {"a": "Nervo Femoral.", "b": "Nervo Fibular Comum (Peroneal).", "c": "Nervo Isquiático.", "d": "Nervo Obturador.", "e": "Nervo Tibial posterior."}, "answer": "b", "rationale": "O nervo fibular comum passa superficialmente ao redor da cabeça da fíbula, sendo muito vulnerável à compressão por suportes de perna inadequadamente acolchoados na posição de litotomia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Lesão de posicionamento cirúrgico clássica.", "c": "Incorreta. Comum na posição de Trendelenburg ou litotomia mas causa sintomas diferentes.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Posicionamento Cirúrgico", "Pós-operatório", "Nervo Fibular", "Pé Caído"]}', 257, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a revascularização miocárdica acorda com incapacidade de realizar a abdução e rotação externa do braço esquerdo, além de fraqueza na flexão do cotovelo. Qual o diagnóstico da lesão por posicionamento?", "options": {"a": "Lesão do Nervo Radial.", "b": "Plexopatia Braquial por tração ou compressão axilar.", "c": "Lesão do Nervo Ulnar.", "d": "AVC medular.", "e": "Osteoartrite súbita."}, "answer": "b", "rationale": "A abertura exagerada do esterno e a posição dos braços podem causar tração ou compressão do plexo braquial, resultando em déficits motores e sensitivos no membro superior.", "option_rationales": {"a": "Incorreta. Nervo radial gera ''mão caída''.", "b": "Correta. Complicação de posicionamento na cirurgia cardíaca/torácica.", "c": "Incorreta. Gera ''mão em garra''.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Plexo Braquial", "Lesão"]}', 258, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o motivo da recomendação de se utilizar ''proteção ocular'' (lubrificante ou fita colante) em pacientes sob anestesia geral profunda?", "options": {"a": "Prevenir a produção de lágrimas.", "b": "Prevenir a abrasão corneana (por dessecação ou trauma direto), uma vez que o paciente perde o reflexo de piscar e a oclusão palpebral pode ser incompleta (lagoftalmo anastésico).", "c": "Melhorar a visão após a cirurgia.", "d": "Evitar conjuntivite alérgica ao pó.", "e": "Evitar o reviramento ocular intenso."}, "answer": "b", "rationale": "A lesão corneana é a complicação ocular mais comum em anestesia geral, causada pela exposição prolongada da córnea ao ar.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Medida de segurança anestésica padrão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Córnea", "Segurança"]}', 259, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''tremores pós-operatórios'' (shivering) é frequente na sala de recuperação e aumenta o consumo de oxigênio do paciente. Qual medicação intravenosa é considerada o padrão-ouro para o tratamento imediato desses tremores?", "options": {"a": "Metoclopramida.", "b": "Meperidina (Dolantina) em doses baixas.", "c": "Dipirona.", "d": "Cetamina.", "e": "Succinilcolina."}, "answer": "b", "rationale": "A meperidina atua reduzindo o limiar de calafrio no hipotálamo, sendo muito eficaz para cessar o tremor pós-anestésico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tratamento farmacológico específico do shivering.", "c": "Incorreta.", "d": "Incorreta. Pode causar agitação e delírios em alguns pacientes.", "e": "Incorreta. Causaria paralisia muscular e parada respiratória se o paciente já estiver extubado."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Tremor", "Meperidina"]}', 260, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a histerectomia abdominal apresenta, no 3º DPO, urina avermelhada constante (hematúria) e dor lombar severa unilateral. No 5º dia, surge drenagem de líquido límpido pálido pela vagina. Qual a complicação?", "options": {"a": "Infecção urinária simples.", "b": "Fístula Ureterovaginal por lesão iatrogênica do ureter durante a cirurgia pélvica.", "c": "Incontinência de esforço.", "d": "Menstruação retardada.", "e": "Ruptura de bexiga somente."}, "answer": "b", "rationale": "A lesão de ureter é um risco clássico na histerectomia (frequentemente no cruzamento com a artéria uterina). A fístula manifesta-se por perda constante de urina pela vagina.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação ureteral clássica em ginecologia operativa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. A fístula vesicovaginal também daria perda de urina, mas a dor lombar sugere acometimento do ureter (obstrução/estravasamento)."}, "difficulty": "media", "tags": ["Ginecologia", "Pós-operatório", "Fístula", "Ureter"]}', 261, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o período mais comum para a ocorrência da ''Atelectasia pós-operatória'', que se manifesta por febre leve (até 38°C), taquipneia e redução de murmúrio vesicular nas bases?", "options": {"a": "Após 14 dias.", "b": "Nas primeiras 24 a 48 horas.", "c": "Durante o ato cirúrgico.", "d": "Apenas em cirurgias de membros inferiores.", "e": "No momento da alta hospitalar."}, "answer": "b", "rationale": "A atelectasia por microcolapso alveolar é a causa mais comum de febre precoce (< 48h) no pós-operatório abdominal e torácico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Febre precoce e fisiopatologia respiratória inicial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Atelectasia", "Febre"]}', 262, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de revascularização femoral para tratamento de isquemia crítica, o paciente desenvolve dor desproporcional ao exame físico, edema tenso e incapacidade de flexão plantar no membro operado. O pulso distal está PAIXADO mas presente. Qual a suspeita?", "options": {"a": "Oclusão aguda do enxerto (Trombose).", "b": "Síndrome Compartimental secundária à reperfusão (edema pós-isquemia).", "c": "Flebite superficial.", "d": "Artrite séptica de joelho.", "e": "Gota aguda."}, "answer": "b", "rationale": "A reperfusão de um membro que estava isquêmico por muito tempo gera um edema muscular intenso. Como os compartimentos são formados por fáscias inextensíveis, a pressão sobe e compromete a microcirculação.", "option_rationales": {"a": "Incorreta. Na oclusão, o pulso estaria ausente e o membro pálido/frio. Na SC, o Pulso é um sinal tardio (pode estar presente no início).", "b": "Correta. Emergência vascular pós-reperfusão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cirurgia Vascular", "Pós-operatório", "Síndrome Compartimental", "Reperfusão"]}', 263, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A conduta definitiva e salvadora para a Síndrome Compartimental aguda de membros inferiores é:", "options": {"a": "Anticoagulação plena apenas.", "b": "Fasciotomia descompressiva (abertura das fáscias de todos os compartimentos afetados).", "c": "Elevacão excessiva do membro.", "d": "Compressão externa com ataduras elásticas.", "e": "Amputação imediata sem tentar outros métodos."}, "answer": "b", "rationale": "Só a abertura mecânica dos compartimentos permite que o tecido edemaciado se expanda sem comprometer a perfusão capilar.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tratamento cirúrgico de emergência padrão.", "c": "Incorreta. Elevacão excessiva pode REDUZIR a pressão de perfusão em um compartimento já pressionado.", "d": "Incorreta. Piora o quadro drasticamente.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Vascular", "Pós-operatório", "Fasciotomia", "Tratamento"]}', 264, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes pediátricos submetidos a adenotonsilectomia (retirada de amígdalas), qual a complicação hemorrágica mais temida que pode ocorrer cerca de 7 a 10 dias após o procedimento?", "options": {"a": "Sangramento por queda da fibrina.", "b": "Sangramento por queda da escara/fibrina da loja amigdaliana após necrose controlada ou descolamento da crosta cicatricial.", "c": "Ruptura de artéria carótida.", "d": "Aumento das plaquetas.", "e": "Gengivorragia leve."}, "answer": "b", "rationale": "A hemorragia tardia pós-adenoamigdalectomia é uma emergência pois pode levar a aspiração de sangue e choque hipovolêmico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fenômeno de sangramento tardio pós-tonsilectomia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Otorrinolaringologia", "Pós-operatório", "Tonsilectomia", "Hemorragia Tardia"]}', 265, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica de reto por via laparoscópica apresenta no 5º DPO dor e distensão abdominal, com saída abundante de líquido quiloso (leitoso) pelo dreno. Qual a causa provável?", "options": {"a": "Fístula da anastomose colorretal (fezes no dreno).", "b": "Ascite Quilosa (lesão de vasos linfáticos de grande importância em retroperitônio durante a linfadenectomia mesentérica).", "c": "Hemorragia ativa.", "d": "Vazamento de pus por abscesso.", "e": "Drenagem de soro glicosado."}, "answer": "b", "rationale": "O líquido leitoso é característico do quilo (rico em triglicerídeos e linfócitos), resultante da ruptura de coletores linfáticos importantes.", "option_rationales": {"a": "Incorreta. O líquido seria turvo, fétido ou francamente entérico.", "b": "Correta. Complicação específica de linfadenectomia oncológica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Oncologia", "Pós-operatório", "Quilo", "Linfáticos"]}', 266, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''icterícia não-obstrutiva'' (predomínio de Bilirrubina Indireta) no pós-operatório de um paciente que recebeu múltiplas transfusões de sangue (politransfundido) é:", "options": {"a": "Cálculo no colédoco.", "b": "Sobrecapara de bilirrubina pela lise das hemácias estocadas e transfundidas (Hematoma reabsorvendo ou hemólise por sangue antigo).", "c": "Obstrução do dreno biliar.", "d": "Apendicite.", "e": "Falta de alimentação."}, "answer": "b", "rationale": "As hemácias estocadas têm menor meia-vida; ao serem transfundidas em massa, o sistema reticuloendotelial as remove, gerando um pico de bilirrubina indireta.", "option_rationales": {"a": "Incorreta. Icterícia obstrutiva é de BI direta.", "b": "Correta. Icterícia por hemólise pós-transfusoão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Hematologia", "Pós-operatório", "Icterícia", "Transfusão"]}', 267, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual complicação anestésica caracteriza-se por contração imediata e involuntária das pregas vocais, impedindo a ventilação, sendo frequente na fase de despertar ou extubação, especialmente em crianças?", "options": {"a": "Broncoespasmo.", "b": "Laringoespasmo.", "c": "Apneia central.", "d": "Soluços persistentes.", "e": "Paralisia diafragmática."}, "answer": "b", "rationale": "O laringoespasmo é uma reação reflexa de proteção da via aérea exacerbada, exigindo ventilação com pressão positiva e, às vezes, relaxantes musculares.", "option_rationales": {"a": "Incorreta. O broncoespasmo ocorre nas vias aéreas inferiores.", "b": "Correta. Emergência em via aérea pediátrica e anestésica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Laringoespasmo", "Emergência"]}', 268, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente que apresenta prolongamento do tempo de despertar anestésico (despertar retardado) após o uso de bloqueadores musculares adespolarizantes durante a cirurgia, deve ser avaliado inicialmente para qual condição farmacogenética?", "options": {"a": "Deficiência de G6PD.", "b": "Deficiência de Pseudocolinesterase plasmática (Butilcolinesterase).", "c": "Hemofilia A.", "d": "Porfiria aguda.", "e": "Anemia falciforme."}, "answer": "b", "rationale": "A pseudocolinesterase é responsável pelo metabolismo da succinilcolina e mivacúrio (e influencia no tempo de outros relaxantes). Deficiências enzimáticas levam a bloqueio neuromuscular prolongado.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Causa farmacogenética de atraso no despertar metabólico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Anestesiologia", "Pós-operatório", "Despertar Retardado", "Farmacogenética"]}', 269, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma correção de aneurisma de aorta abdominal (laparotomia), o paciente apresenta dor abdominal, diarreia sanguinolenta e leucocitose. A hipótese é isquemia colônica. Qual o próximo passo diagnóstico IMEDIATO?", "options": {"a": "Colonoscopia ou retossigmoidoscopia para avaliar a viabilidade da mucosa.", "b": "Cintilografia óssea.", "c": "Apenas observar por 24 horas.", "d": "Iniciar antibiótico e aguardar alta.", "e": "Laparotomia imediata sem exames."}, "answer": "a", "rationale": "A mucosa é a camada mais sensível à isquemia. A visualização direta permite avaliar se há necrose que exija reoperação e ressecção do cólon.", "option_rationales": {"a": "Correta. Exame padrão para diagnóstico de colite isquêmica pós-op aórtico.", "b": "Incorreta.", "c": "Incorreta. Atrasar o diagnóstico de necrose transmural é fatal.", "d": "Incorreta.", "e": "Incorreta. Pode-se evitar a cirurgia se a isquemia for apenas leve/superficial."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "Isquemia Colônica", "Colonoscopia"]}', 270, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação iatrogênica do uso de placas e parafusos metálicos para fixação de fraturas expostas de alto grau?", "options": {"a": "Osteoporose.", "b": "Infecção de Sítio Cirúrgico profunda (Osteomielite) por formação de biofilme bacteriano no implante.", "c": "Excesso de cálcio no sangue.", "d": "Redução do tamanho do osso.", "e": "Alergia ao ferro."}, "answer": "b", "rationale": "Materiais estranhos (implantes) facilitam a fixação bacteriana. Nas fraturas expostas, o risco é inerente à contaminação inicial e manipulação cirúrgica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco infeccioso em cirurgia ortopédica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ortopedia", "Pós-operatório", "Infecção", "Implante"]}', 271, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente no 4º DPO de uma cirurgia de grande porte queixa-se de visão borrada e sensação de corpo estranho no olho esquerdo. Ao exame, há hiperemia conjuntival e o teste com fluoresceína mostra uma mancha verde brilhante. Qual o diagnóstico?", "options": {"a": "Uveíte anterior.", "b": "Abrasão Corneana (Úlcera de córnea traumática/dessecação).", "c": "Glaucoma de ângulo fechado.", "d": "Descolamento de retina.", "e": "Hemorragia vítrea."}, "answer": "b", "rationale": "O teste de fluoresceína evidencia falhas no epitélio da córnea, confirmando a abrasão, complicação comum por proteção ocular inadequada no intraoperatório.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico clínico e do exame complementar.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Oftalmologia", "Pós-operatório", "Abrasão Corneana", "Diagnóstico"]}', 272, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''hemoperitônio'' imediato após uma biópsia hepática percutânea ou videolaparoscópica é:", "options": {"a": "Ruptura de varizes esofágicas.", "b": "Lesão traumática de vasos hepáticos ou da cápsula de Glisson não detectada.", "c": "Hipertensão portal isolada.", "d": "Falta de vitamina C.", "e": "Ascite infectada."}, "answer": "b", "rationale": "A biópsia é um procedimento invasivo que pode atingir vasos sanguíneos no parênquima hepático, causando sangramento para a cavidade abdominal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco hemorrágico do procedimento.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Gastroenterologia", "Pós-operatório", "Biópsia Hepática", "Hemorragia"]}', 273, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma neurocirurgia para tumor de fossa posterior, o paciente apresenta poliúria súbita (> 250 ml/h de urina clara) e sódio sérico de 155 mEq/L (hipernatremia). Qual o diagnóstico?", "options": {"a": "SIADH.", "b": "Diabetes Insipidus central (falta de ADH).", "c": "Diabetes Mellitus descompensado.", "d": "Embolia pulmonar.", "e": "Choque Séptico."}, "answer": "b", "rationale": "A manipulação de estruturas próximas ao hipotálamo/hipófise pode suspender a secreção de ADH, fazendo o rim excretar água livre em excesso.", "option_rationales": {"a": "Incorreta. SIADH daria hiponatremia e oligúria relativa.", "b": "Correta. Quadro clínico clássico de DI pós-op neurológico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Neurocirurgia", "Pós-operatório", "Diabetes Insipidus", "Sódio"]}', 274, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''quilotórax'' após esofagectomia pode ser tratada inicialmente de forma conservadora. Qual a base dietética deste tratamento para reduzir o débito de quilo?", "options": {"a": "Dieta rica em gorduras animais.", "b": "Dieta com Triglicerídeos de Cadeia Média (TCM) ou Nutrição Parenteral Total.", "c": "Dieta rica em fibras apenas.", "d": "Dieta hipoproteica.", "e": "Não há dieta específica."}, "answer": "b", "rationale": "O objetivo é evitar que gorduras de cadeia longa, que são absorvidas pelos linfáticos, aumentem o fluxo de quilo através da fístula do ducto torácico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manejo dietético específico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Nutrologia", "Pós-operatório", "Quilotórax", "Tratamento"]}', 275, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de grande porte, observa-se que o paciente apresenta oligúria (débito < 0,5 ml/kg/h). Ao realizar um exame de imagem, nota-se hidronefrose bilateral. Qual a etiologia da insuficiência renal aguda?", "options": {"a": "Pré-renal.", "b": "Pós-renal (obstrutiva), por exemplo, por ligadura inadvertida de ureteres ou cateterismo vesical obstruído.", "c": "Renal (NTA).", "d": "Choque anafilático.", "e": "Hemólise aguda."}, "answer": "b", "rationale": "A hidronefrose é o sinal radiológico de obstrução ao fluxo urinário; no pós-operatório pélvico complexo, a ligadura de ambos os ureteres é uma causa iatrogênica grave.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico morfológico de obstrução.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Nefrologia", "Pós-operatório", "IRA", "Hidronefrose"]}', 276, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação do uso do ''eletrocautério'' (bisturi elétrico) em pacientes portadores de marca-passo cardíaco não-programado para o modo cirúrgico?", "options": {"a": "Explosão do aparelho.", "b": "Interferência eletromagnética (EMI) que pode desprogramar o marca-passo, causar perda de captura ou inibir o estímulo cardíaco, levando a bradicardia grave.", "c": "Aumentar a carga da bateria do marca-passo.", "d": "Infeccção do bolso do gerador.", "e": "Drenagem de secreção pelo marca-passo."}, "answer": "b", "rationale": "O bisturi elétrico gera uma corrente de alta frequência que os aparelhos de marca-passo podem confundir com a atividade elétrica do coração, cessando seu funcionamento.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco técnico em pacientes com dispositivos eletrônicos implantáveis.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Pós-operatório", "Marca-passo", "Segurança"]}', 277, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma paratireoidectomia total, o paciente apresenta no 1º DPO parestesias periorais e Sinal de Chvostek (espasmo facial ao percutir o nervo facial). Qual o distúrbio metabólico subjacente?", "options": {"a": "Hipercalcemia aguda.", "b": "Hipocalcemia aguda.", "c": "Hipocalemia grave.", "d": "Hipernatremia.", "e": "Acidose respiratória."}, "answer": "b", "rationale": "A queda brusca do PTH causa hipocalcemia aguda, aumentando a excitabilidade neuromuscular.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação esperada e cuidada no pós-op de tireoide/paratireoide.", "c": "Incorreta. Hipocalemia causa fraqueza, não tetania tipicamente.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Endocrinologia", "Pós-operatório", "Hipocalcemia", "Chvostek"]}', 278, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A Síndrome da ''Alça Cega'' ou Alça Aferente após cirurgia Billroth II manifesta-se tipicamente por qual queixa neurológica no contexto de uma complicação tardia?", "options": {"a": "Convulsão súbita.", "b": "Deficiência de Vitamina B12 por supercrescimento bacteriano na alça desativada (que consome a vitamina).", "c": "Paralisia facial.", "d": "Surdez unilateral.", "e": "Cegueira noturna."}, "answer": "b", "rationale": "O estase na alça aferente favorece o crescimento de bactérias que competem pela vitamina B12, levando à anemia megaloblástica e sintomas neurológicos (degeneração combinada subaguda).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Consequência metabólica tardia de complicação cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Clínica Médica", "Pós-operatório", "B12", "Alça Cega"]}', 279, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual complicação após cirurgia abdominal se caracteriza pela inversão (prolapso) de uma parte do intestino para dentro de outra, podendo ser causada por pontos de sutura ou drenos que servem como ponto de apoio?", "options": {"a": "Vólvulo.", "b": "Intussuscepção (Invaginação intestinal).", "c": "Diverticulite.", "d": "Fecaloma.", "e": "Hérnia de hiato."}, "answer": "b", "rationale": "Embora mais comum em crianças (idiopática), a intussuscepção no adulto pós-operado pode ocorrer por fatores mecânicos iatrogênicos ou lesões pré-existentes.", "option_rationales": {"a": "Incorreta. Vólvulo é a torção sobre o próprio eixo.", "b": "Correta. Definição correta do mecanismo.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Intussuscepção", "Mecânica"]}', 280, 'draft')
